      SUBROUTINE COMBINCC     PERFORM ALGEBRAIC OPERATIONS AND EVALUATE FUNCTIONSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM23.CIN'CC     LOCAL VARIABLESC      REAL            DREGA(NPVAR), DREGB(NPVAR), DREGC(NPVAR)      EXTERNAL        DATARCC-------------------------------------------------------------C     INPUT REGISTERS AND OPERATIONC      K1 = K1REG      K2 = K2REG      J = JREG      NP1 = NV3 + 1      IF (JTIE .EQ. 0 .AND. J .GT. 20) GO TO 500      IF (K1TIE .EQ. 0 .AND. K1 .GT. 20) GO TO 500CC     FIRST OPERANDC      IF (K1TIE .EQ. 100) GO TO 20      IF (.NOT. LREG(K1)) GO TO 500      REGA = REG(K1)      IF (NV3 .EQ. 0) GO TO 50      DO 5 JJ = 1, NV3    5 DREGA(JJ) = DREG(K1,JJ)      IF (NV3 .GE. NPVAR) GO TO 50   10 DO 15 JJ = NP1, NPVAR   15 DREGA(JJ) = 0.0      GO TO 50C   20 REGA = DATAR(K1)      IF (NV3 .EQ. 0) GO TO 50      DO 25 JJ = 1, NV3   25 DREGA(JJ) = 0.0      NV2 = K1   27 NV2 = TIE(NV2)      IF (NV2 .EQ. 100) GO TO 27      IF (NV2 .EQ. 0) GO TO 50      IF (NV2 .EQ. 99) GO TO 30      DREGA(NV2) = 1.0      GO TO 50C   30 IF (NV3 .EQ. 0) GO TO 50      DO 35 JJ = 1, NV3   35 DREGA(JJ) = DATA(K1+JJ)CC     SECOND OPERANDC   50 IF (IOPN .GT. 4) GO TO 100      IF (K2TIE .EQ. 0 .AND. K2 .GT. 20) GO TO 500      IF (K2TIE .EQ. 100) GO TO 70      IF (.NOT. LREG(K2)) GO TO 500      REGB = REG(K2)      IF (NV3 .EQ. 0) GO TO 100      DO 55 JJ = 1, NV3   55 DREGB(JJ) = DREG(K2,JJ)      IF (NV3 .GE. NPVAR) GO TO 100   60 DO 65 JJ = NP1, NPVAR   65 DREGB(JJ) = 0.0      GO TO 100C   70 REGB = DATAR(K2)      IF (NV3 .EQ. 0) GO TO 100      DO 75 JJ = 1, NV3   75 DREGB(JJ) = 0.0      NV2 = K2   77 NV2 = TIE(NV2)      IF (NV2 .EQ. 100) GO TO 77      IF (NV2 .EQ. 0) GO TO 100      IF (NV2 .EQ. 99) GO TO 80      DREGB(NV2) = 1.0      GO TO 100C   80 IF (NV3 .EQ. 0) GO TO 100      DO 85 JJ = 1, NV3   85 DREGB(JJ) = DATA(K2+JJ)CC     OPERATIONSC  100 IF (NV3 .EQ. 0) GO TO 106      IF (NV3 .GE. NPVAR) GO TO 106      DO 105 JJ = NP1, NPVAR  105 DREGC(JJ) = 0.0  106 IF (IOPN .LT. 10) THEN        GO TO (110,120,130,140), IOPN      ELSE        IGO = IOPN - 11        GO TO (150,160,170,180,190,200,210,220,230,240), IGO      ENDIFCC     ADDITIONC  110 REGC = REGA + REGB      IF (NV3 .EQ. 0) GO TO 500      DO 115 N = 1, NV3  115 DREGC(N) = DREGA(N) + DREGB(N)      GO TO 500CC     SUBTRACTIONC  120 REGC = REGA - REGB      IF (NV3 .EQ. 0) GO TO 500      DO 125 N = 1, NV3  125 DREGC(N) = DREGA(N) - DREGB(N)      GO TO 500CC     MULTIPLICATIONC  130 PROD = REGA*REGB      IF (NV3 .EQ. 0) GO TO 138      DO 135 N = 1, NV3  135 DREGC(N) = REGA*DREGB(N) + DREGA(N)*REGB  138 REGC = PROD      GO TO 500CC     DIVISIONC  140 QUOT = REGA/REGB      IF (NV3 .EQ. 0) GO TO 148      DO 145 N = 1, NV3  145 DREGC(N) = (REGB*DREGA(N) - REGA*DREGB(N))/REGB**2  148 REGC = QUOT      GO TO 500CC     NEGATIVEC  150 REGC = - REGA      IF (NV3 .EQ. 0) GO TO 500      DO 155 N = 1, NV3  155 DREGC(N) = - DREGA(N)      GO TO 500CC     SQUARE ROOTC  160 ROOT = SQRT(REGA)      IF (NV3 .GT. 0) THEN        DO 165 N = 1, NV3  165   DREGC(N) = 0.5*DREGA(N)/ROOT      ENDIF      REGC = ROOT      GO TO 500CC     LOGARITHMC  170 XLOG = LOG(REGA)      IF (NV3 .GT. 0) THEN        DO 175 N = 1, NV3  175   DREGC(N) = DREGA(N)/REGA      ENDIF      REGC = XLOG      GO TO 500CC     EXPONENTIALC  180 EXPX = EXP(REGA)      IF (NV3 .GT. 0) THEN        DO 185 N = 1, NV3  185   DREGC(N) = EXPX*DREGA(N)      ENDIF      REGC = EXPX      GO TO 500CC     SINEC  190 SINX = SIN(REGA)      IF (NV3 .GT. 0) THEN        COSX = COS(REGA)        DO 195 N = 1, NV3  195   DREGC(N) = COSX*DREGA(N)      ENDIF      REGC = SINX      GO TO 500CC     COSINEC  200 COSX = COS(REGA)      IF (NV3 .GT. 0) THEN        SINX = SIN(REGA)        DO 205 N = 1, NV3  205   DREGC(N) = - SINX*DREGA(N)      ENDIF      REGC = COSX      GO TO 500CC     HYPERBOLIC SINEC  210 SINHX = SINH(REGA)      IF (NV3 .GT. 0) THEN        COSHX = COSH(REGA)        DO 215 N = 1, NV3  215   DREGC(N) = COSHX*DREGA(N)      ENDIF      REGC = SINHX      GO TO 500CC     HYPERBOLIC COSINEC  220 COSHX = COSH(REGA)      IF (NV3 .GT. 0) THEN        SINHX = SINH(REGA)        DO 225 N = 1, NV3  225   DREGC(N) = SINHX*DREGA(N)      ENDIF      REGC = COSHX      GO TO 500CC     ARCSINEC  230 ASINX = ASIN(REGA)      IF (NV3 .GT. 0) THEN        SKORT = 1.0/SQRT(1.0 - REGA**2)        DO 235 N = 1, NV3  235   DREGC(N) = SKORT*DREGA(N)      ENDIF      REGC = ASINX      GO TO 500CC     ARCCOSINEC  240 ACOSX = ACOS(REGA)      IF (NV3 .GT. 0) THEN        SKORT = - 1.0/SQRT(1.0 - REGA**2)        DO 245 N = 1, NV3  245   DREGC(N) = SKORT*DREGA(N)      ENDIF      REGC = ACOSX      GO TO 500CC     STORE RESULT OF OPERATIONC  500 IF (JTIE .EQ. 100) GO TO 520      REG(J) = REGC      LREG(J) = .TRUE.      IF (NV3 .EQ. 0) GO TO 550      DO 505 JJ = 1, NV3  505 DREG(J,JJ) = DREGC(JJ)      GO TO 550C  520 DATA(J) = REGC      IF (NV3 .EQ. 0) GO TO 550      DO 525 JJ = 1, NV3  525 DATA(J+JJ) = DREGC(JJ)C  550 RETURN      END